    "detail": {
      "republicDay": {
        "about": "गणतंत्र दिवस हर साल 26 जनवरी को मनाया जाता है। इस दिन 1950 में, भारत अपने स्वयं के संविधान के साथ एक गणतंत्र बन गया — नियमों की एक बड़ी पुस्तक जो सभी को निष्पक्ष और सुरक्षित रहने में मदद करती है। स्कूल ध्वज समारोह, परेड और देशभक्ति गीत आयोजित करते हैं।",
        "funFact": "क्या आप जानते हैं? गणतंत्र दिवस की एक भव्य परेड नई दिल्ली में मार्चिंग सैनिकों, रंगीन फ्लोट्स और विभिन्न राज्यों के नृत्य के साथ होती है!",
        "try": "एक सैनिक की तरह खड़े हो जाओ, धीरे से सलाम करो, और कहो \"{name}!\" केसरिया, सफ़ेद और हरी पट्टियों के साथ तिरंगे का झंडा खींचें।"
      },
      "independenceDay": {
        "about": "स्वतंत्रता दिवस 15 अगस्त को मनाया जाता है। यह उस दिन को चिह्नित करता है जब भारत 1947 में स्वतंत्र हुआ था। लोग राष्ट्रीय ध्वज फहराते हैं, देशभक्ति के गीत गाते हैं, और उन बहादुर स्वतंत्रता सेनानियों को याद करते हैं जिन्होंने हमारे देश के लिए कड़ी मेहनत की।",
        "funFact": "क्या आप जानते हैं? प्रधान मंत्री हर स्वतंत्रता दिवस पर दिल्ली के लाल किले पर ध्वजारोहण करते हैं जबकि भारत भर में पतंगें उड़ती हैं!",
        "try": "हवा में एक झंडे की तरह अपना हाथ हिलाओ और कहो \"{name}!\" एक बात बताओ जो तुम्हें भारत के बारे में पसंद है।"
      },
      "gandhiJayanti": {
        "about": "गांधी जयंती 2 अक्टूबर को राष्ट्रपिता महात्मा गांधी का जन्मदिन मनाती है। उसने शांति, सत्य और अहिंसा की शिक्षा दी। इस दिन, लोग दयालुता से बोलना, दूसरों की मदद करना और परिवेश को साफ रखना याद करते हैं।",
        "funFact": "क्या आप जानते हैं? गांधी जी ने साधारण कपड़ों का इस्तेमाल किया और शांति और एकता के अपने संदेश को फैलाने के लिए लंबी दूरी तय की!",
        "try": "दस चरणों के लिए धीरे-धीरे और चुपचाप चलें। \"{name}!\" कहें और अपने कमरे को साफ रखने के लिए कागज का एक टुकड़ा उठाएं।"
      },
      "childrensDay": {
        "about": "बाल दिवस भारत में 14 नवंबर को मनाया जाता है — जवाहरलाल नेहरू का जन्मदिन, जो बच्चों से प्यार करते थे और उन्हें राष्ट्र का भविष्य कहते थे। स्कूल केवल बच्चों के लिए मजेदार कार्यक्रम, खेल, मिठाई और विशेष गतिविधियाँ आयोजित करते हैं।",
        "funFact": "क्या तुम्हें पता था? नेहरू जी को अक्सर चाचा नेहरू कहा जाता था क्योंकि वह बच्चों की बहुत परवाह करते थे!",
        "try": "बड़ा मुस्कुराओ और कहो \"{name}!\" जब आप बड़े होते हैं तो एक बड़े व्यक्ति को एक सपना बताएं।"
      },
      "teachersDay": {
        "about": "शिक्षक दिवस 5 सितंबर को मनाया जाता है — भारत के महान शिक्षक और पूर्व राष्ट्रपति डॉ. सर्वपल्ली राधाकृष्णन का जन्मदिन। छात्र कार्ड, फूल और गाने के साथ शिक्षकों का धन्यवाद करते हैं।",
        "funFact": "क्या आप जानते हैं? डॉ. राधाकृष्णन ने कहा कि उनके जन्मदिन को व्यक्तिगत अवकाश के बजाय शिक्षक दिवस के रूप में मनाया जाए!",
        "try": "\"{name}\" कहें और एक शिक्षक को धन्यवाद दें कि उन्होंने आपको कुछ सिखाया है।"
      },
      "constitutionDay": {
        "about": "26 नवंबर को संविधान दिवस (संविधान दिवस) उस दिन को याद करता है जब भारत ने 1949 में अपना संविधान अपनाया था। स्कूल मौलिक अधिकारों, कर्तव्यों और कैसे कानून नागरिकों को समान और स्वतंत्र रखते हैं, के बारे में पढ़ते हैं।",
        "funFact": "क्या आप जानते हैं? डॉ. बी. आर. अम्बेडकर को भारतीय संविधान का मुख्य वास्तुकार कहा जाता है!",
        "try": "\"{name}\" कहें और एक अच्छे नियम का नाम दें जो घर या स्कूल में सभी की मदद करता है।"
      },
      "nationalYouthDay": {
        "about": "राष्ट्रीय युवा दिवस 12 जनवरी को स्वामी विवेकानंद का जन्मदिन मनाता है, जिन्होंने युवाओं को बहादुर, दयालु और मन और शरीर में मजबूत होने के लिए प्रेरित किया।",
        "funFact": "क्या आप जानते हैं? स्वामी विवेकानंद ने शिकागो में एक प्रसिद्ध भाषण दिया जिसने दुनिया को भारतीय ज्ञान की प्रशंसा की!",
        "try": "लंबा खड़े हो जाओ, सूर्योदय की तरह अपनी बाहों को फैलाओ, और कहो \"{name}!\" अपने लिए एक बहादुर लक्ष्य साझा करें।"
      },
      "nationalUnityDay": {
        "about": "राष्ट्रीय एकता दिवस (राष्ट्रीय एकता दिवस) 31 अक्टूबर को सरदार वल्लभ भाई पटेल का सम्मान करता है, जिन्होंने कई राज्यों को एक भारत में एकजुट करने में मदद की। लोग एकता और एकजुटता का संकल्प लेते हैं।",
        "funFact": "क्या आप जानते हैं? पटेल को देश के राज्यों को एक साथ लाने के लिए भारत का लौह पुरुष कहा जाता है!",
        "try": "एक दोस्त का हाथ धीरे से पकड़ें और कहें \"{name}!\" बताएँ कि दोस्त और पड़ोसी क्यों मायने रखते हैं।"
